-- Migration 007: listing photos (derivatives are generated by the media layer).

CREATE TABLE IF NOT EXISTS listing_photos (
    id          BIGSERIAL PRIMARY KEY,
    listing_id  INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
    hash        TEXT NOT NULL,
    path        TEXT NOT NULL,
    thumb_path  TEXT NOT NULL,
    width       INTEGER NOT NULL,
    height      INTEGER NOT NULL,
    bytes       INTEGER NOT NULL,
    position    INTEGER NOT NULL DEFAULT 0,
    is_cover    BOOLEAN NOT NULL DEFAULT FALSE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (listing_id, hash)
);

CREATE INDEX IF NOT EXISTS idx_listing_photos_listing
    ON listing_photos (listing_id, position);

-- At most one cover photo per listing.
CREATE UNIQUE INDEX IF NOT EXISTS idx_listing_photos_one_cover
    ON listing_photos (listing_id) WHERE is_cover;
